function shiftRanges(s: string, shifts: number[][]): string {
  const net = new Array(s.length).fill(0);
  for (const [a, b, d] of shifts) for (let i = a; i <= b; i++) net[i] += d === 1 ? 1 : -1;
  let out = "";
  for (let i = 0; i < s.length; i++) {
    const c = (((s.charCodeAt(i) - 97 + net[i]) % 26) + 26) % 26;
    out += String.fromCharCode(97 + c);
  }
  return out;
}

