class Solution:
    def shiftRanges(self, s: str, shifts: List[List[int]]) -> str:
        net = [0] * len(s)
        for a, b, d in shifts:
            for i in range(a, b + 1):
                net[i] += 1 if d == 1 else -1
        return "".join(chr(97 + (ord(c) - 97 + net[i]) % 26) for i, c in enumerate(s))

