function shiftRanges(s: string, shifts: number[][]): string {
  const n = s.length;
  const diff = new Array(n + 1).fill(0);
  for (const [a, b, d] of shifts) {
    const v = d === 1 ? 1 : -1;
    diff[a] += v;
    diff[b + 1] -= v;
  }
  const out: string[] = [];
  let run = 0;
  for (let i = 0; i < n; i++) {
    run += diff[i];
    const c = (((s.charCodeAt(i) - 97 + run) % 26) + 26) % 26;
    out.push(String.fromCharCode(97 + c));
  }
  return out.join("");
}

